-- Recetario de barra — Cantina Dos Santos (Medellín) y Dos Santos Cali
-- 41 subrecetas (SUBB, con su rendimiento) + 285 productos de carta (CS, rinden 1 UN).
-- Área "Barra" de: dos-santos, dos-santos-cali-mtg0p7fs. No borra nada: si un código ya existe en esa área, no se duplica.
--
-- Correcciones aplicadas al listado (aprobadas por Miguel):
--   - CUBA LIBRE: SLIC014 es COCA COLA ZERO pero el nombre dice COCA REGULAR → se usa SLIC013 (COCA REGULAR INS)
--   - LONG ISLAND ICE TEA: SLIC014 es COCA COLA ZERO pero el nombre dice COCA REGULAR → se usa SLIC013 (COCA REGULAR INS)
--   - shot de margarita: 45 GR → 45 ML (el mix rinde en litros)
--   - AURORA DEL ARENAL: almíbar de miel 20 GR → 20 ML
--   - AD.CLAMATO: 45 GR → 45 ML
--   - soda 30 ML → 0,1 UN (botella), como en la Herencia
--   - ZUMO GROSELLA: ácido láctico 4 ML → 4 GR
--   - MARGARITA SHAKE: miel de agave 7,5 ML → 10 GR
--
-- Ajustes y avisos:
--   - ESPUMA TAMARINDO SALADA rinde "0.4 GR" y se usa en ML (Fuego Tropical) → 0,4 L
--   - SUBB021 PIÑA TAJIN rinde "0.86 GR" → se toma como 0.86 KG
--   - SUBB025 PURE DURAZNO rinde "0.75 GR" → se toma como 0.75 KG
--   - SUBB027 SAL CITRICA rinde "0.5 GR" → se toma como 0.5 KG
--   - MERMELADA DE CHAMOY rinde "0.8 L" y se usa en GR (La Mano) → 0,8 KG (aprobado)
--   - Insumo BAR122: se unifica el nombre "TAJIN" → "TAJIN BAR INS"
--   - Insumo LIC156: se unifica el nombre "VODKA SMIRNOFF" → "BT.SMIRNOFF INS"
--   - Insumo BAR062: se unifica el nombre "GOTAS AMARGAS" → "GOTAS AMARGAS INS"
--   - Insumo LIC120: se unifica el nombre "BT.LICOR DE CAFÉ COLOMA INS" → "BT. LICOR DE CAFE COLOMA INS"
--   - Insumo BAR125: se unifica el nombre "TORONJA BAR" → "TORONJA BAR INS"
--   - Insumo LIC157: se unifica el nombre "BT. SMIRNOFF TAMARINDO" → "BT.SMIRNOFF TAMARINDO INS"
--   - Insumo LIC027: se unifica el nombre "APEROL" → "BT.APEROL INS"
--   - Insumo SUBB010: se unifica el nombre "ESPUMA DE TAMARINDO SALADA" → "ESPUMA TAMARINDO SALADA"
--   - Insumo SUBB039: se unifica el nombre "ZUMO DE GROSELLA" → "ZUMO GROSELLA"
--   - Insumo BAR141: se unifica el nombre "GROSELLAS" → "GROSELLA"
--   - Insumo LIC055: se unifica el nombre "BT, CENTENARIO REPOSADO INS" → "BT. CENTENARIO REPOSADO INS"
--   - Insumo BAR004: se unifica el nombre "ACIDO CITRICO" → "ACIDO CITRICO BAR INS"
--   - Insumo BAR005: se unifica el nombre "ACIDO LACTICO" → "ACIDO LACTICO BAR INS"
--
-- UNIDADES CRUZADAS (se cargan tal cual; la app no puede calcular el costo de estas líneas hasta corregirlas):
--   (ninguno)

-- 0) Verificación: debe existir un área "Barra" en cada punto. Si falta alguna, no se carga nada.
do $$
declare n int;
begin
  select count(*) into n from public.areas a join public.locations l on l.id = a.location_id
  where l.slug in ('dos-santos', 'dos-santos-cali-mtg0p7fs') and lower(trim(a.name)) = 'barra';
  if n <> 2 then
    raise exception 'Se esperaban 2 áreas "Barra" (una por punto) y hay %: no se cargó nada', n;
  end if;
end $$;

